from collections import defaultdict

def mapper(docs):
    pairs = []
    for doc in docs:
        for word in doc.lower().split():
            pairs.append((word, 1))
    return pairs

def shuffle_and_sort(mapped_pairs):
    temp = defaultdict(list)
    for key, val in mapped_pairs:
        temp[key].append(val)
    return {k: temp[k] for k in sorted(temp.keys())}

def reducer(grouped):
    return {k: sum(vals) for k, vals in grouped.items()}

