import numpy as np

def _metrics(y_true, y_pred):
    err = y_true - y_pred
    mae = float(np.mean(np.abs(err)))
    rmse = float(np.sqrt(np.mean(err ** 2)))
    mape = float(np.mean(np.abs(err / y_true)) * 100.0)
    return {'mae': round(mae, 4), 'rmse': round(rmse, 4), 'mape': round(mape, 4)}

def evaluate_basic_forecast(series, window=3):
    arr = np.asarray(series, dtype=float)
    y_true = arr[window:]
    y_naive = arr[window - 1 : -1]
    y_ma = np.array([np.mean(arr[t - window : t]) for t in range(window, len(arr))])
    return {'naive': _metrics(y_true, y_naive), 'ma': _metrics(y_true, y_ma)}

