from sklearn.model_selection import TimeSeriesSplit

def first_difference(series):
    return np.diff(np.asarray(series, dtype=float), n=1)

def temporal_cv_rmse(series, n_splits=3):
    arr = np.asarray(series, dtype=float)
    X = np.column_stack([arr[1:-1], arr[:-2]])
    y = arr[2:]
    tscv = TimeSeriesSplit(n_splits=n_splits)
    rmses = []
    for train_idx, test_idx in tscv.split(X):
        model = LinearRegression().fit(X[train_idx], y[train_idx])
        pred = model.predict(X[test_idx])
        rmses.append(float(np.sqrt(np.mean((y[test_idx] - pred) ** 2))))
    return round(float(np.mean(rmses)), 4)

import hashlib
from collections import Counter

def _age_bucket(age):
    if age < 30:
        return '18-29'
    if age < 50:
        return '30-49'
    return '50+'

def anonymize_and_check_k(records, k=2):
    anon = []
    qi_counts = Counter()
    for r in records:
        token = hashlib.sha256(r['username'].encode('utf-8')).hexdigest()[:12]
        ag = _age_bucket(r['age'])
        qi_counts[(ag, r['city'])] += 1
        anon.append({
            'user_token': token,
            'age_group': ag,
            'city': r['city'],
            'sentiment': r['sentiment'],
        })
    is_k_anon = len(qi_counts) > 0 and min(qi_counts.values()) >= k
    return anon, is_k_anon

