from collections import defaultdict

def process_telecom_logs(crm_records, call_logs):
    seen_ids = set()
    totals = defaultdict(int)
    for log in call_logs:
        cid = log['call_id']
        uid = log['user_id']
        dur = log['duration_sec']
        if uid not in crm_records or cid in seen_ids:
            continue
        seen_ids.add(cid)
        if dur is None or dur <= 0:
            continue
        totals[crm_records[uid]] += dur
    return dict(totals)

