import math

def simulate_hdfs_allocation(files, block_size_mb=128, replication=3):
    per_file = {}
    tot_log = 0
    tot_phys = 0
    for name, size in files:
        lb = math.ceil(size / block_size_mb) if size > 0 else 0
        pb = lb * replication
        per_file[name] = {'logical_blocks': lb, 'physical_blocks': pb}
        tot_log += lb
        tot_phys += pb
    return {
        'per_file': per_file,
        'total_logical_blocks': tot_log,
        'total_physical_blocks': tot_phys,
    }

