def yarn_allocate_containers(nodes, jobs):
    rem = {n['node_id']: {'vcores': n['vcores'], 'ram_gb': n['ram_gb']} for n in nodes}
    order = [n['node_id'] for n in nodes]
    assigned = {}
    unscheduled = []
    for jid, rv, rr in jobs:
        placed = False
        for nid in order:
            if rem[nid]['vcores'] >= rv and rem[nid]['ram_gb'] >= rr:
                rem[nid]['vcores'] -= rv
                rem[nid]['ram_gb'] -= rr
                assigned[jid] = nid
                placed = True
                break
        if not placed:
            unscheduled.append(jid)
    return {'assigned': assigned, 'unscheduled': unscheduled, 'remaining': rem}

