from collections import defaultdict

def tumbling_event_window(events, window_sec=10):
    buckets = defaultdict(list)
    for ts, val in events:
        w_start = (ts // window_sec) * window_sec
        buckets[w_start].append(val)
    return {
        w: {'count': len(vals), 'sum': round(sum(vals), 4)}
        for w, vals in sorted(buckets.items())
    }

import pandas as pd

def eda_summary_and_corr(df, threshold=0.85):
    stats = {}
    for col in df.columns:
        stats[col] = {
            'mean': round(float(df[col].mean()), 4),
            'median': round(float(df[col].median()), 4),
            'std': round(float(df[col].std()), 4),
        }
    corr = df.corr().abs()
    cols = sorted(df.columns)
    pairs = []
    for i in range(len(cols)):
        for j in range(i + 1, len(cols)):
            val = float(corr.loc[cols[i], cols[j]])
            if val >= threshold:
                pairs.append((cols[i], cols[j], round(val, 4)))
    return {'stats': stats, 'high_corr_pairs': pairs}

import numpy as np

def manual_kmeans(X, init_centroids, max_iter=10):
    pts = np.asarray(X, dtype=float)
    cents = np.asarray(init_centroids, dtype=float).copy()
    labels = np.zeros(len(pts), dtype=int)
    for _ in range(max_iter):
        dists = np.linalg.norm(pts[:, None, :] - cents[None, :, :], axis=2)
        new_labels = np.argmin(dists, axis=1)
        if np.array_equal(new_labels, labels) and _ > 0:
            break
        labels = new_labels
        for k in range(len(cents)):
            mask = labels == k
            if np.any(mask):
                cents[k] = pts[mask].mean(axis=0)
    wcss = 0.0
    for k in range(len(cents)):
        mask = labels == k
        if np.any(mask):
            wcss += float(np.sum((pts[mask] - cents[k]) ** 2))
    return labels.tolist(), np.round(cents, 4).tolist(), round(wcss, 4)

