import numpy as np

def ses_forecast(series, alpha):
    y = [float(v) for v in series]
    f = [y[0]]
    for t in range(1, len(y)):
        f.append(alpha * y[t - 1] + (1.0 - alpha) * f[t - 1])
    nxt = alpha * y[-1] + (1.0 - alpha) * f[-1]
    err = np.array(y[1:]) - np.array(f[1:])
    rmse = float(np.sqrt(np.mean(err ** 2)))
    return [round(v, 4) for v in f], round(float(nxt), 4), round(rmse, 4)

def best_ses_alpha(series, alphas):
    results = [(a, ses_forecast(series, a)[2]) for a in alphas]
    return min(results, key=lambda item: item[1])

import math
from collections import Counter

def _gini(y):
    n = len(y)
    if n == 0:
        return 0.0
    return 1.0 - sum((c / n) ** 2 for c in Counter(y).values())

def _entropy(y):
    n = len(y)
    if n == 0:
        return 0.0
    return -sum((c / n) * math.log2(c / n) for c in Counter(y).values() if c > 0)

def split_impurity_gain(parent_labels, left_labels, right_labels):
    n = len(parent_labels)
    wl = len(left_labels) / n
    wr = len(right_labels) / n
    pg = _gini(parent_labels)
    pe = _entropy(parent_labels)
    gg = pg - (wl * _gini(left_labels) + wr * _gini(right_labels))
    ig = pe - (wl * _entropy(left_labels) + wr * _entropy(right_labels))
    return {
        'parent_gini': round(pg, 4),
        'parent_entropy': round(pe, 4),
        'gini_gain': round(gg, 4),
        'info_gain': round(ig, 4),
    }

