def tune_knn_pipeline(X, y, k_list):
    X_tr, X_te, y_tr, y_te = train_test_split(
        X, y, test_size=0.3, random_state=42, stratify=y
    )
    scaler = StandardScaler()
    X_tr_s = scaler.fit_transform(X_tr)
    X_te_s = scaler.transform(X_te)
    best = {'best_k': None, 'best_metric': None, 'best_accuracy': -1.0}
    for m in ['euclidean', 'manhattan']:
        for k in k_list:
            clf = KNeighborsClassifier(n_neighbors=k, metric=m).fit(X_tr_s, y_tr)
            acc = round(float(accuracy_score(y_te, clf.predict(X_te_s))), 4)
            if acc > best['best_accuracy']:
                best = {'best_k': k, 'best_metric': m, 'best_accuracy': acc}
    return best

