from collections import defaultdict

def _part(k, n):
    return sum(ord(c) for c in k) % n

def check_and_rebalance_partitions(keys, num_partitions=4):
    raw = [0] * num_partitions
    for k in keys:
        raw[_part(k, num_partitions)] += 1
    avg = len(keys) / num_partitions
    is_skewed = max(raw) > 2.0 * avg
    seen = defaultdict(int)
    bal = [0] * num_partitions
    for k in keys:
        salt = seen[k] % num_partitions
        seen[k] += 1
        bal[_part(f'{k}_{salt}', num_partitions)] += 1
    return {'raw_counts': raw, 'is_skewed': is_skewed, 'balanced_counts': bal}

